import{_ as t,H as a,f as n,i as s}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"11 | 地球往事：为什么CV领域首先引领预训练潮流？","description":"","frontmatter":{},"headers":[{"level":2,"title":"视觉模型的发展之路","slug":"视觉模型的发展之路","link":"#视觉模型的发展之路","children":[{"level":3,"title":"CNN：初出茅庐","slug":"cnn-初出茅庐","link":"#cnn-初出茅庐","children":[]},{"level":3,"title":"AlexNet：一鸣惊人","slug":"alexnet-一鸣惊人","link":"#alexnet-一鸣惊人","children":[]},{"level":3,"title":"ResNet：冲破瓶颈","slug":"resnet-冲破瓶颈","link":"#resnet-冲破瓶颈","children":[]}]},{"level":2,"title":"视觉算法的社会价值","slug":"视觉算法的社会价值","link":"#视觉算法的社会价值","children":[]},{"level":2,"title":"视觉预训练模型原理","slug":"视觉预训练模型原理","link":"#视觉预训练模型原理","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"AI大模型系统实战/11｜地球往事：为什么CV领域首先引领预训练潮流？.md","filePath":"AI大模型系统实战/11｜地球往事：为什么CV领域首先引领预训练潮流？.md","lastUpdated":1795452834000}'),i={name:"AI大模型系统实战/11｜地球往事：为什么CV领域首先引领预训练潮流？.md"};function l(p,e,r,o,E,h){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="_11-地球往事-为什么cv领域首先引领预训练潮流" tabindex="-1">11 | 地球往事：为什么CV领域首先引领预训练潮流？ <a class="header-anchor" href="#_11-地球往事-为什么cv领域首先引领预训练潮流" aria-label="Permalink to &quot;11 | 地球往事：为什么CV领域首先引领预训练潮流？&quot;">​</a></h1><p>你好，我是 Tyler。</p><p>今天我们要开启一个全新的章节——技术原理篇。从今天开始，我们正式进入 AI 大模型的学习。在这节课中，主要学习内容是视觉预训练模型（Pre-Training Model，PTM）。</p><p>你可能会问，为什么要先讲预训练模型呢？很好的问题，我们所说的 AI 大模型，其实就是一种预训练模型。预训练模型会使用海量的数据对模型做长时间的预先训练，这能让它拥有强大的知识储备，更好地解决各个领域的问题。</p><p>我会带你深入学习“预训练技术”和“大模型技术”的发展历程，帮助你理解它们的来龙去脉，以便更好地学习大语言模型中的预训练方法。</p><h2 id="视觉模型的发展之路" tabindex="-1">视觉模型的发展之路 <a class="header-anchor" href="#视觉模型的发展之路" aria-label="Permalink to &quot;视觉模型的发展之路&quot;">​</a></h2><p>在开始预训练技术的学习之前，我们先来了解一下“大模型”的发展历程。</p><p>大模型这个概念在视觉领域并不陌生，第一代大模型技术就来自视觉领域。故事的开始还要从1943 年说起，那一年神经生物学家 MeCulloch 与青年数学家 Pitts 合作，基于生物神经网络的工作特点，提出了第一个人工神经网络模型。</p><p>在此之后，神经科学成为了人工智能最重要的交叉学科之一。随着这两个学科交叉的不断深入，涌现出了各种伟大的仿生神经网络，其中最经典的网络就有我们即将学习的卷积神经网络（Convolutional Neural Networks, CNN）。</p><h3 id="cnn-初出茅庐" tabindex="-1">CNN：初出茅庐 <a class="header-anchor" href="#cnn-初出茅庐" aria-label="Permalink to &quot;CNN：初出茅庐&quot;">​</a></h3><p>我们人类在处理视觉内容时天赋很高。相信你也会有这样的体会，看过一个东西之后，脑海中的图像记忆，远比声音和文字要深刻得多。所以研究人员总隐隐觉得生物的视觉机制更加精巧和智能，一直在尝试各种方法，用计算机去对图像处理的能力进行建模。</p><p>幸运的是，这个问题由于神经科学的新发现有了转机。什么？想要解答一道计算机应用题，首先要学的竟然是生物学知识？我这就带你看看这背后的故事。</p><p>1981 年，哈佛大学的休伯尔和维泽尔发现了视觉中的简单细胞和复杂细胞这两种类型的细胞。</p><ul><li><p>简单细胞是在视网膜中发现的，它们是视觉系统的第一级神经元，对特定方向和空间位置的光敏性很强。有助于提取观测对象各种形状的边缘信息，可以拼凑勾勒出不同物体的轮廓。</p></li><li><p>复杂细胞是在初级视觉皮层中发现的，它们是在简单细胞之后的第二级神经元，在信号的传递过程中不会改变特征的位置和方向。</p></li></ul><p>休伯尔和维泽尔的一系列研究获得了诺贝尔奖，也为卷积神经网络的发展奠定了基础。随后LeCun 基于这项发现，提出了卷积神经网络（CNN）。</p><ul><li><p>CNN 的卷积层类似于简单细胞，通过将卷积算子作为滤波器。提取物体的视觉边缘信息，形成局部特征，并只与上一层局部区域相连接。</p></li><li><p>CNN 的池化层则类似于复杂细胞，通过提取信号最强的部分，对底层的边缘特征进一步的聚合，同样确保了信号在传递中不改变位置和方向。</p></li></ul><p>我在后面准备了一张 CNN 的示意图，方便你直观对比两类细胞和 CNN 网络之间的关系。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/11/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/11/1.png" alt=""></a></p><p>通过这种分层的特征传递方式，即使视觉目标在图像中移动位置，顶层的特征表示也不会改变。我们不由感叹生物构造进化的奇妙，这种平移不变的特性特别适合解决视觉任务中的各种问题。</p><p>早在 1998 年 LeNet-5 就成功使用下图中的 CNN 网络解决了手写数字识别的任务，并定义了CNN 的基本结构。然而，由于当时训练 CNN 所需的计算资源非常庞大，学术界和产业界都没有进一步研究它的想法，只是把它看成实验室中的一种“玩具”封存了起来。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/11/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/11/2.png" alt=""></a></p><ul><li>LeNet-5 模型架构</li></ul><h3 id="alexnet-一鸣惊人" tabindex="-1">AlexNet：一鸣惊人 <a class="header-anchor" href="#alexnet-一鸣惊人" aria-label="Permalink to &quot;AlexNet：一鸣惊人&quot;">​</a></h3><p>直到 2009 年，李飞飞等研究员在 CVPR 2009 上发表了 ImageNet: A Large-ScaleHierarchical Image Database，这篇论文正式拉开 ImageNet 挑战赛的历史序幕，推动了整个计算机视觉领域的发展。</p><p>这个时期的 GPU 性能不断提高，人们的视野被拉回到那些性能开销大但值得一试的方法，革命性的方法呼之欲出。</p><p>直到 2012 年，Hinton 教授的团队终于通过利用一些沿用至今的训练技巧（包括 ReLU 激活函数、Dropout 正则化和数据增强）以及两块 GTX 580 GPU，让下图中 CNN 架构的 AlexNet取得了突破性的成果，在 ImageNet 竞赛中一举夺冠。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/11/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/11/3.png" alt=""></a></p><ul><li>AlexNet 模型架构</li></ul><p>AlexNet 的成功，为深度学习领域带来了革命性的变化，从此深度学习成为了计算机视觉领域的主流算法。</p><p>值得一提的是，在这个时期，一家伟大的公司也在冉冉升起，那就是 NVIDIA。NVIDIA 早期在CUDA 上的布局让他迅速在深度学习的高性能计算（HPC）领域形成了绝对优势。如今，NVIDIA 已经成为市值过万亿美元的巨头公司了。</p><h3 id="resnet-冲破瓶颈" tabindex="-1">ResNet：冲破瓶颈 <a class="header-anchor" href="#resnet-冲破瓶颈" aria-label="Permalink to &quot;ResNet：冲破瓶颈&quot;">​</a></h3><p>也是在 AlexNet 之后，人们开始尝试使用更多的 GPU，来训练更深的神经网络。这时人们发现，在模型的网络层数不断增加后，出现了梯度消失和梯度爆炸的情况。这让研究人员在工作中变得畏首畏尾，不敢大规模地增加模型的层数，深度学习有些“深”不下去了。</p><p>这时候深度残差网络（ResNet）应运而生。ResNet 是 CNN 图像史上的一件里程碑事件，它可以让模型在大幅增加层数的同时，突破梯度爆炸的瓶颈，达到更高的准确性，这个能力让它在 ImageNet 和 COCO 等比赛中拿到了五项第一的好成绩。</p><p>那 ResNet 的解题思路是怎样的呢？它通过设计特殊的直通通道，引入了许多旁路直接连接到后续层。这就相当于让领导和员工直接见面，避免传话过程中信息的丢失。这个设计让模型可以绕过深层网络中的梯度爆炸和消失问题，更好地学习复杂的图像特征。</p><p>你可以先看看后面的示意图，再听我讲解 ResNet 残差模块的特别之处。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/11/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/11/4.png" alt=""></a></p><p>左图是常规的残差模块，由两个 3×3 的卷积核组成。然而，随着网络进一步加深，这种残差结构在实践中效果比较有限。</p><p>而右图的“瓶颈残差模块”（bottleneck residual block）效果更好。这是因为，ResNet 的瓶颈残差模块由 1x1、3x3 和 1x1 的卷积层依次堆叠而成。其中，1x1 的卷积层可以起到降维或升维的作用，使得 3x3 的卷积操作可以在相对较低维度的输入上进行，从而提高计算效率。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/11/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/11/5.png" alt=""></a></p><p>ResNet 这篇论文成为了 CV 领域乃至整个 AI 领域引用最多的文章之一，它的价值可想而知。</p><p>ResNet 的成功为深度学习领域带来了革命性的变化，随后基于 ResNet 诞生的 DenseNet、Inception 等网络结构的层数越来越深，参数量过亿已司空见惯。</p><p>超大参数模型的出现，让 ImageNet 这类公开大规模数据集发挥了未曾预料的作用。之后又有越来越多普惠的视觉 PTM 发布出来。</p><p>所谓的大模型技术在这时已初显雏形，这些工作都为后续大模型发展奠定了坚实的模型工程基础，积累了宝贵的实践经验。</p><h2 id="视觉算法的社会价值" tabindex="-1">视觉算法的社会价值 <a class="header-anchor" href="#视觉算法的社会价值" aria-label="Permalink to &quot;视觉算法的社会价值&quot;">​</a></h2><p>刚刚我们学到的视觉大模型的发展，对预训练模型技术的推动作用不容小觑。然而，视觉模型的高速商业化进程，也给视觉预训练技术的发展带来了重要影响。</p><p>十二年前，几名来自清华大学的学生共同创立了四小龙中最早成立的旷视科技。这时以人脸识别算法（旷世的英文名就是 Face++）为代表的视觉算法进入了快速发展阶段，更多的人开始直观地感受到人工智能技术的价值，各种 AI 概念的创业公司陆续涌现。</p><p>那时社会上几乎所有的 AI 领域投资都在向 “产业互联网 = 视觉算法 + AIoT” 的模式靠拢，商业需求这只巨大的手推动着视觉算法的发展。</p><p>然而，产业互联网的算法研发模式和之前大不相同。例如，推荐算法只要有一个固定的算法团队，对若干场景的模型做长期稳定的调优即可。</p><p>但这在产业互联网中则不行。例如，如果把为银行准备的视觉安防模型拿给餐饮店去使用，这肯定不现实。因为客户对数据隐私保护的需求十分强烈，你不能使用各个客户的数据去交叉训练同一个模型。</p><p>因此，为了满足特定的需求，算法团队每天都在重复使用新场景的数据来训练定制的模型。这将带来无尽的重复工作，消耗本来就稀缺的算法工程师资源。</p><p>如果这时候你能够通过单一模型快速适应新场景，就能帮你的公司赢得巨大的成本优势。于是，研发人员开始广泛采用公开数据集 + 大模型预训练的方法，配合领域微调的技术，用来降低面向不同业务场景定制化开发的成本。</p><p>因此，随着产业互联网的发展，大模型预训练 + 领域微调这种方式，逐渐成为了视觉算法研发的主流。</p><h2 id="视觉预训练模型原理" tabindex="-1">视觉预训练模型原理 <a class="header-anchor" href="#视觉预训练模型原理" aria-label="Permalink to &quot;视觉预训练模型原理&quot;">​</a></h2><p>接下来，我将以人脸检测算法为例，带你学习视觉预训练模型的特点。</p><p>预训练大模型在视觉领域兴起还有一个至关重要的因素，那就是预训练技术在视觉领域的可解释性更好。你可以先结合后面这张图观察一下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/11/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/11/6.png" alt=""></a></p><ul><li>人脸识别算法模型分层结构示意图</li></ul><p>可以看到，这个人脸检测算法的构成其实是有一定的分层特点的。</p><ul><li><p>左侧的底层网络正在构建基础的“边缘检测能力”。</p></li><li><p>中层的网络则利用这些边缘信息，来组成更高层次目标的局部特征，中间这张图显示的五官信息，就是一个典型的表现。</p></li><li><p>最上层则会出现和我们的目标分类任务最相关的一些实体，在这个例子中就是人脸的内容。</p></li></ul><p>这种分层结构非常适合用来做模型的领域微调，只需要使用较少的数据，更新最上层也就是负责分类功能部分的模型参数，就能够获得良好的效果。</p><p>在搞清原理之后，后面模型领域微调和我们上一章学过的模型训练没有太大的不同。</p><p>这里我只提一个关键点，假设你已经在开源社区得到了一个使用 ImageNet 训练好的预训练模型，你需要将最后一层的连接替换成你的输出格式再进行训练（详见下图和代码）即可。当然你也可以再往后面加上几层网络，来增加模型的深度和拟合效果，这个留作你的课后作业进行练习。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/11/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/AI%E5%A4%A7%E6%A8%A1%E5%9E%8B%E7%B3%BB%E7%BB%9F%E5%AE%9E%E6%88%98/images/11/7.png" alt=""></a></p><ul><li>预训练模型微调流程示意图</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># … 加载数据</span></span>
<span class="line"><span># 加载预训练的ResNet-50模型</span></span>
<span class="line"><span>model = models.resnet50(pretrained=True)</span></span>
<span class="line"><span># 替换最后一层全连接层</span></span>
<span class="line"><span>num_ftrs = model.fc.in_features</span></span>
<span class="line"><span>model.fc = nn.Linear(num_ftrs, len(image_datasets[&#39;train&#39;].classes))</span></span>
<span class="line"><span># 定义损失函数和优化器</span></span>
<span class="line"><span>criterion = nn.CrossEntropyLoss()</span></span>
<span class="line"><span>optimizer = optim.SGD(model.parameters(), lr=0.001, momentum=0.9)</span></span>
<span class="line"><span># 将模型迁移到GPU上（如果可用）</span></span>
<span class="line"><span>device = torch.device(&quot;cuda:0&quot; if torch.cuda.is_available() else &quot;cpu&quot;)</span></span>
<span class="line"><span>model = model.to(device)</span></span>
<span class="line"><span># … 训练模型</span></span></code></pre></div><p>虽然随着大模型的发展，针对各种大模型微调的工具越来越多，在 AI 大模型上已经不再直接使用这种方式去微调（其实也可以就是费钱），但是总体的思路是完全相同的。在下一章中，我将带你学习如何高效地微调一个大规模参数的 AIGC 模型，敬请期待。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>学到这里我们做个总结吧，其实计算机视觉预训练大模型的发展受到了商业和技术因素的双轮驱动。</p><ul><li><p>在商业上，人脸识别等人工智能应用的发展，吸引了许多投资者对相关产业进行投资建设，提供了持续的需求，也促进了成本更低和更准确可靠模型的不断推出。</p></li><li><p>在技术上，ResNet 和 ImageNet 等视觉领域的创新发展，使视觉大模型的训练成为可能，为视觉大模型的出现提供了必要条件。</p></li></ul><p>除此之外，你还学习了模型预训练相关的知识。</p><ul><li><p>首先，在预训练阶段，你需要让模型学习通识知识（如 ImageNet），为后续专业知识的学习打下基础。</p></li><li><p>随后，在微调阶段，你需要为模型提供各个专业领域的定制化知识（如人脸识别），这就像高中的文理分科教学，或大学阶段的专业学科教育一样。</p></li></ul><p>事实上，像 ChatGPT 这样的 NLP 预训练大模型，也是通过使用大量通识教育数据先训练学习基础的“语言知识”，然后通过各个领域的专业资料学习“世界知识”。</p><p>这听起来似乎很简单，但将视觉预训练模型的这些经验应用到自然语言处理（NLP）领域经历了漫长的过程。你可以先猜一下它是如何实现的，接下来的课程里，我将为你揭晓答案。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>预训练模型和大模型之间的关系是什么？</p><p>恭喜完成我们第 11 次打卡学习，期待你在留言区和我交流互动。如果你觉得有收获，也欢迎你分享给你身边的朋友，邀 TA 一起讨论。</p>`,76)])])}const A=t(i,[["render",l]]);export{u as __pageData,A as default};
